1	<!DOCTYPE html>
2	<!-- -->
3	<html lang="en">
4	<head>
5	<meta charset="UTF-8" />
6	<meta name="viewport" content="width=device-width, initial-scale=1.0" />
7	<title>Chick – Network Map Prototype</title>
8	<style>
9	  :root {
10	    --bg: #fbf8ff;
11	    --surface: #f2efff;
12	    --surface2: #eae7ff;
13	    --border: #dcd6f5;
14	    --accent: #7b6fdb;
15	    --accent2: #9b91e8;
16	    --accent3: #c4bcff;
17	    --accent4: #a78bfa;
18	    --warning: #c4401a;
19	    --text: #120d1e;
20	    --text2: #3d3358;
21	    --text3: #8f86ad;
22	    --font-display: Georgia, 'Iowan Old Style', 'Palatino Linotype', 'Book Antiqua', serif;
23	    --font: -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
24	    --mono: 'SF Mono', Menlo, Consolas, monospace;
25	  }
26	  * { box-sizing: border-box; margin: 0; padding: 0; }
27	  body {
28	    background-color: var(--bg);
29	    background-image: repeating-linear-gradient(
30	      to bottom,
31	      transparent, transparent 30px,
32	      rgba(43,36,24,0.05) 31px
33	    );
34	    color: var(--text);
35	    font-family: var(--font);
36	    height: 100vh;
37	    overflow: hidden;
38	  }
39	  .screen {
40	    position: fixed;
41	    inset: 0;
42	    display: none;
43	    align-items: center;
44	    justify-content: center;
45	    flex-direction: column;
46	  }
47	  .screen.active { display: flex; }
48	  #screen-input {
49	    overflow-y: auto;
50	    padding: 40px 0;
51	  }
52	
53	  /* ── SCREEN 1: INPUT ── */
54	  .input-layout {
55	    display: flex;
56	    align-items: center;
57	    gap: 56px;
58	    max-width: 920px;
59	    padding: 0 24px;
60	  }
61	  .hero-copy {
62	    max-width: 320px;
63	    flex-shrink: 0;
64	  }
65	  .hero-copy .logo { text-align: left; margin-bottom: 18px; }
66	  .hero-tagline {
67	    font-family: var(--font-display);
68	    color: var(--accent);
69	    font-size: 15px;
70	    font-weight: 600;
71	    margin-bottom: 10px;
72	  }
73	  .hero-headline {
74	    font-family: var(--font-display);
75	    font-size: 27px;
76	    font-weight: 700;
77	    line-height: 1.2;
78	    color: var(--text);
79	  }
80	  .hero-headline em {
81	    font-style: italic;
82	    font-weight: 400;
83	    color: var(--accent2);
84	  }
85	  #screen-input .card {
86	    width: 400px;
87	    flex-shrink: 0;
88	    background: var(--surface);
89	    border: 1px solid var(--border);
90	    border-radius: 16px;
91	    padding: 32px;
92	    box-shadow: 0 10px 30px rgba(43,36,24,0.08);
93	  }
94	  @media (max-width: 780px) {
95	    .input-layout { flex-direction: column; gap: 28px; }
96	    .hero-copy { text-align: center; max-width: 400px; }
97	    .hero-copy .logo { text-align: center; }
98	  }
99	  .logo {
100	    font-family: var(--font-display);
101	    font-size: 24px;
102	    font-weight: 700;
103	    margin-bottom: 24px;
104	    text-align: center;
105	    color: var(--text);
106	    letter-spacing: -0.3px;
107	    display: flex;
108	    align-items: center;
109	    justify-content: center;
110	    gap: 8px;
111	  }
112	  .logo span { color: var(--accent); }
113	  .logo-icon {
114	    width: 30px;
115	    height: 30px;
116	    flex-shrink: 0;
117	    border-radius: 50%;
118	    background-image: url('logo_CHICK.jpeg');
119	    background-size: 95px 95px;
120	    background-position: -29px -14px;
121	    background-repeat: no-repeat;
122	    box-shadow: 0 2px 6px rgba(43,36,24,0.15);
123	  }
124	  .hero-copy .logo { justify-content: flex-start; }
125	  label {
126	    display: block;
127	    font-size: 11px;
128	    font-weight: 700;
129	    text-transform: uppercase;
130	    letter-spacing: 0.6px;
131	    color: var(--text2);
132	    margin: 14px 0 6px;
133	  }
134	  input, textarea, select {
135	    width: 100%;
136	    background: var(--surface2);
137	    border: 1px solid var(--border);
138	    border-radius: 8px;
139	    color: var(--text);
140	    font-family: var(--font);
141	    font-size: 14px;
142	    padding: 11px 13px;
143	    outline: none;
144	  }
145	  input:focus, textarea:focus, select:focus { border-color: var(--accent); }
146	  textarea { min-height: 70px; resize: vertical; }
147	  .btn {
148	    width: 100%;
149	    padding: 14px;
150	    margin-top: 20px;
151	    background: linear-gradient(135deg, var(--accent), #5b4fb8);
152	    border: none;
153	    border-radius: 10px;
154	    color: #fff8ee;
155	    font-size: 15px;
156	    font-weight: 700;
157	    cursor: pointer;
158	    box-shadow: 0 6px 18px rgba(123,111,219,0.3);
159	  }
160	  .btn:disabled { opacity: 0.5; cursor: not-allowed; }
161	  .btn-ghost {
162	    background: var(--surface);
163	    border: 1px solid var(--border);
164	    color: var(--text2);
165	    width: auto;
166	    padding: 9px 18px;
167	    font-size: 13px;
168	    border-radius: 999px;
169	    box-shadow: 0 2px 8px rgba(43,36,24,0.06);
170	  }
171	
172	  /* ── SCREEN 2: MAP ── */
173	  #screen-map { flex-direction: row; align-items: stretch; justify-content: flex-start; }
174	  .side-panel {
175	    width: 300px;
176	    flex-shrink: 0;
177	    height: 100%;
178	    overflow-y: auto;
179	    background: var(--surface);
180	    border-right: 1px solid var(--border);
181	    padding: 110px 18px 24px;
182	    box-sizing: border-box;
183	  }
184	  .side-panel-label {
185	    font-family: var(--mono);
186	    font-size: 10px;
187	    letter-spacing: 1.2px;
188	    text-transform: uppercase;
189	    color: var(--accent);
190	    font-weight: 700;
191	    margin-bottom: 4px;
192	  }
193	  .side-panel-sub {
194	    font-size: 11px;
195	    color: var(--text3);
196	    margin-bottom: 16px;
197	  }
198	  .panel-card {
199	    background: var(--bg);
200	    border: 1px solid var(--border);
201	    border-radius: 12px;
202	    padding: 12px 14px;
203	    margin-bottom: 10px;
204	  }
205	  .panel-card-top {
206	    display: flex;
207	    align-items: center;
208	    justify-content: space-between;
209	    margin-bottom: 6px;
210	  }
211	  .panel-score {
212	    font-family: var(--font-display);
213	    font-size: 20px;
214	    font-weight: 700;
215	    color: var(--accent);
216	  }
217	  .panel-badge {
218	    font-size: 10px;
219	    font-weight: 700;
220	    color: var(--accent);
221	    background: rgba(123,111,219,0.12);
222	    border: 1px solid var(--border);
223	    border-radius: 999px;
224	    padding: 3px 9px;
225	    white-space: nowrap;
226	  }
227	  .panel-name {
228	    font-weight: 700;
229	    font-size: 14px;
230	    color: var(--text);
231	    margin-bottom: 3px;
232	  }
233	  .panel-meta {
234	    font-size: 11px;
235	    color: var(--text2);
236	    line-height: 1.4;
237	  }
238	  #screen-map .map-stage-wrap {
239	    flex: 1;
240	    position: relative;
241	    height: 100%;
242	  }
243	  .map-header {
244	    position: absolute;
245	    top: 24px;
246	    left: 32px;
247	    right: 32px;
248	    display: flex;
249	    justify-content: space-between;
250	    align-items: center;
251	    z-index: 10;
252	  }
253	  .map-ruler {
254	    position: absolute;
255	    top: 96px;
256	    left: 50%;
257	    transform: translateX(-50%);
258	    text-align: center;
259	    z-index: 4;
260	  }
261	  .map-ruler-line {
262	    width: 260px;
263	    height: 1px;
264	    background: var(--text3);
265	    margin: 0 auto 8px;
266	  }
267	  .map-ruler-label {
268	    font-family: var(--mono);
269	    font-size: 11px;
270	    letter-spacing: 1.5px;
271	    color: var(--text2);
272	    text-transform: uppercase;
273	  }
274	  .map-hint {
275	    position: absolute;
276	    bottom: 28px;
277	    left: 0; right: 0;
278	    text-align: center;
279	    color: var(--text3);
280	    font-size: 13px;
281	  }
282	  .map-stage {
283	    position: relative;
284	    width: 100%;
285	    height: 100%;
286	  }
287	  .center-node {
288	    position: absolute;
289	    top: 50%; left: 50%;
290	    transform: translate(-50%, -50%);
291	    width: 110px; height: 110px;
292	    border-radius: 50%;
293	    background: radial-gradient(ellipse at 38% 32%, #c4bcff 0%, #a78bfa 50%, #7b6fdb 100%);
294	    display: flex;
295	    align-items: center;
296	    justify-content: center;
297	    text-align: center;
298	    font-family: var(--font-display);
299	    font-weight: 700;
300	    font-size: 13px;
301	    color: #fff8ee;
302	    padding: 10px;
303	    box-shadow: 0 16px 36px rgba(91,79,184,0.35), inset 0 -6px 16px rgba(0,0,0,0.15);
304	    z-index: 5;
305	  }
306	  .orbit-node {
307	    position: absolute;
308	    top: 50%; left: 50%;
309	    border-radius: 50%;
310	    display: flex;
311	    flex-direction: column;
312	    align-items: center;
313	    justify-content: center;
314	    gap: 2px;
315	    text-align: center;
316	    color: #fff8ee;
317	    cursor: pointer;
318	    padding: 8px;
319	    line-height: 1.2;
320	    overflow: hidden;
321	    box-shadow: 0 14px 22px rgba(43,36,24,0.32), 0 2px 5px rgba(43,36,24,0.18);
322	    transition: transform 0.2s, box-shadow 0.2s;
323	    opacity: 0;
324	    animation: nodeIn 0.5s ease forwards;
325	  }
326	  .orbit-node .node-name {
327	    font-weight: 700;
328	    word-break: break-word;
329	  }
330	  .orbit-node .node-score {
331	    font-weight: 600;
332	    opacity: 0.85;
333	    white-space: nowrap;
334	  }
335	  .orbit-node:hover {
336	    transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(1.1) !important;
337	    box-shadow: 0 18px 30px rgba(43,36,24,0.4), 0 3px 6px rgba(43,36,24,0.2);
338	    z-index: 8;
339	  }
340	  @keyframes nodeIn {
341	    from { opacity: 0; transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(0.4); }
342	    to   { opacity: 1; transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(1); }
343	  }
344	  .connector {
345	    position: absolute;
346	    top: 50%; left: 50%;
347	    height: 1px;
348	    background: linear-gradient(90deg, rgba(123,111,219,0.35), transparent);
349	    transform-origin: left center;
350	    z-index: 1;
351	  }
352	
353	  /* ── SCREEN 3: PLAYBOOK FULLSCREEN ── */
354	  #screen-playbook {
355	    flex-direction: column;
356	    align-items: stretch;
357	    justify-content: flex-start;
358	    overflow-y: auto;
359	    padding: 40px 60px;
360	  }
361	  .playbook-top {
362	    display: flex;
363	    justify-content: space-between;
364	    align-items: center;
365	    margin-bottom: 28px;
366	  }
367	  .playbook-title { font-family: var(--font-display); font-size: 32px; font-weight: 700; color: var(--text); }
368	  .tag {
369	    display: inline-block;
370	    font-size: 12px;
371	    font-weight: 700;
372	    padding: 4px 12px;
373	    border-radius: 20px;
374	    background: rgba(123,111,219,0.12);
375	    color: var(--accent);
376	    margin-top: 8px;
377	  }
378	  .pb-grid {
379	    display: grid;
380	    grid-template-columns: 1fr 1fr;
381	    gap: 18px;
382	    max-width: 1000px;
383	    margin: 0 auto;
384	    width: 100%;
385	  }
386	  .pb-card {
387	    background: var(--surface);
388	    border: 1px solid var(--border);
389	    border-radius: 14px;
390	    padding: 22px;
391	    box-shadow: 0 6px 18px rgba(43,36,24,0.06);
392	  }
393	  .pb-card.full { grid-column: 1 / -1; }
394	  .pb-card h3 {
395	    font-size: 11px;
396	    text-transform: uppercase;
397	    letter-spacing: 1px;
398	    color: var(--accent);
399	    margin-bottom: 14px;
400	  }
401	  .pb-card ul { list-style: none; }
402	  .pb-card li {
403	    font-size: 14px;
404	    color: var(--text2);
405	    padding: 7px 0;
406	    border-bottom: 1px solid var(--border);
407	  }
408	  .pb-card li:last-child { border-bottom: none; }
409	  .post-body, .dm { white-space: pre-wrap; font-size: 13px; color: var(--text2); line-height: 1.7; }
410	  .center-loading {
411	    display: flex;
412	    flex-direction: column;
413	    align-items: center;
414	    justify-content: center;
415	    height: 100%;
416	    gap: 16px;
417	  }
418	  .spinner {
419	    width: 36px; height: 36px;
420	    border: 3px solid var(--border);
421	    border-top-color: var(--accent);
422	    border-radius: 50%;
423	    animation: spin 0.8s linear infinite;
424	  }
425	  @keyframes spin { to { transform: rotate(360deg); } }
426	</style>
427	</head>
428	<body>
429	
430	<!-- SCREEN 1: INPUT -->
431	<div class="screen active" id="screen-input">
432	  <div class="input-layout">
433	    <div class="hero-copy">
434	      <div class="logo"><span class="logo-icon"></span>Chick<span>.</span></div>
435	      <div class="hero-tagline">Your GTM Co-Founder for Founders</div>
436	      <div class="hero-headline">From idea<br>to <em>first user.</em></div>
437	    </div>
438	    <div class="card">
439	    <label>Startup Name</label>
440	    <input id="s-name" placeholder="e.g. NoteAI" value="NoteAI" />
441	    <label>What does it do?</label>
442	    <textarea id="s-desc">AI tool that automatically writes session notes for therapists after each client call, saving 2+ hours per day</textarea>
443	    <label>Target customer</label>
444	    <input id="s-customer" value="Independent therapists running private practices" />
445	    <label>Stage</label>
446	    <select id="s-stage">
447	      <option value="idea">Idea stage</option>
448	      <option value="pre-launch" selected>Pre-launch</option>
449	      <option value="launched">Launched (0-100 users)</option>
450	      <option value="growing">Growing (100+ users)</option>
451	    </select>
452	    <label>Sector</label>
453	    <select id="s-category">
454	      <option value="healthtech" selected>Healthtech / Wellness</option>
455	      <option value="b2b-saas">B2B SaaS</option>
456	      <option value="fintech">Fintech</option>
457	      <option value="edtech">Edtech</option>
458	      <option value="developer-tools">Developer Tools</option>
459	      <option value="ai">AI / ML</option>
460	      <option value="general-startup">Other / General</option>
461	    </select>
462	    <button class="btn" id="find-btn" onclick="findCommunities()">Map My Network →</button>
463	    <button class="btn btn-ghost" style="margin-top:10px" onclick="loadDemoData()">🧪 Preview with demo data</button>
464	    </div>
465	  </div>
466	</div>
467	
468	<!-- SCREEN 2: MAP -->
469	<div class="screen" id="screen-map">
470	  <div class="side-panel">
471	    <div class="side-panel-label">Top communities for your ICP</div>
472	    <div class="side-panel-sub">Verified via Cala — no hallucinated names, no dead groups.</div>
473	    <div id="side-panel-list"></div>
474	  </div>
475	  <div class="map-stage-wrap">
476	    <div class="map-header">
477	      <div class="logo"><span class="logo-icon"></span>Chick<span>.</span></div>
478	      <button class="btn btn-ghost" onclick="goToScreen('screen-input')">← Start over</button>
479	    </div>
480	    <div class="map-ruler">
481	      <div class="map-ruler-line"></div>
482	      <div class="map-ruler-label" id="map-ruler-label">Communities found</div>
483	    </div>
484	    <div class="map-stage" id="map-stage"></div>
485	    <div class="map-hint">Click a community to generate its activation playbook</div>
486	  </div>
487	</div>
488	
489	<!-- SCREEN 3: PLAYBOOK -->
490	<div class="screen" id="screen-playbook">
491	  <div class="playbook-top">
492	    <div>
493	      <div class="playbook-title" id="pb-title">—</div>
494	      <span class="tag" id="pb-platform">—</span>
495	    </div>
496	    <button class="btn btn-ghost" onclick="goToScreen('screen-map')">← Back to map</button>
497	  </div>
498	  <div id="pb-body"></div>
499	</div>
500	
501	<script>
502	const API_BASE = '/api';
503	let currentStartup = null;
504	let currentCommunities = [];
505	
506	function goToScreen(id) {
507	  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
508	  document.getElementById(id).classList.add('active');
509	}
510	
511	function loadDemoData() {
512	  currentStartup = {name:'NoteAI', description:'x', target_customer:'therapists', stage:'pre-launch', category:'healthtech'};
513	  goToScreen('screen-map');
514	  renderMap([
515	    {name:'r/therapists', platform:'Reddit', relevance_score:92},
516	    {name:'Therapist Slack', platform:'Slack', relevance_score:85},
517	    {name:'r/HealthTech', platform:'Reddit', relevance_score:78},
518	    {name:'Build In Public Discord', platform:'Discord', relevance_score:65}
519	  ]);
520	}
521	
522	async function findCommunities() {
523	  currentStartup = {
524	    name: document.getElementById('s-name').value.trim(),
525	    description: document.getElementById('s-desc').value.trim(),
526	    target_customer: document.getElementById('s-customer').value.trim(),
527	    stage: document.getElementById('s-stage').value,
528	    category: document.getElementById('s-category').value,
529	  };
530	  if (!currentStartup.name || !currentStartup.description || !currentStartup.target_customer) {
531	    alert('Please fill in all fields.');
532	    return;
533	  }
534	
535	  const btn = document.getElementById('find-btn');
536	  btn.disabled = true;
537	  btn.textContent = 'Searching 2,847 communities...';
538	  const loadingStages = setTimeout(() => {
539	    btn.textContent = 'Verifying via Cala — no hallucinated names, no dead groups...';
540	  }, 1400);
541	
542	  try {
543	    const res = await fetch(`${API_BASE}/find-communities`, {
544	      method: 'POST',
545	      headers: { 'Content-Type': 'application/json' },
546	      body: JSON.stringify(currentStartup),
547	    });
548	    if (!res.ok) throw new Error(await res.text());
549	    const data = await res.json();
550	    currentCommunities = data.communities;
551	    goToScreen('screen-map');
552	    renderMap(currentCommunities);
553	  } catch (err) {
554	    alert('Error connecting to API. Is the backend running on port 8000?\n\n' + err.message);
555	  } finally {
556	    clearTimeout(loadingStages);
557	    btn.disabled = false;
558	    btn.textContent = 'Map My Network →';
559	  }
560	}
561	
562	const PLATFORM_COLORS = {
563	  'Reddit': '#8f5fd1',
564	  'Discord': '#5b7fd1',
565	  'Slack': '#b06fc9',
566	  'Facebook': '#6a6fc4',
567	  'LinkedIn': '#5f8fc9',
568	  'Forum': '#9b7fd6',
569	  'Newsletter': '#7a5fb0',
570	  'Meetup': '#c470a8',
571	  'Twitter/X': '#4a4a68',
572	};
573	
574	function displayName(name) {
575	  return name.replace(/^r\//i, '');
576	}
577	
578	function renderSidePanel(communities) {
579	  const list = document.getElementById('side-panel-list');
580	  list.innerHTML = communities.map((c, i) => {
581	    const score = c.relevance_score || 70;
582	    return `
583	      <div class="panel-card">
584	        <div class="panel-card-top">
585	          <span class="panel-score">${score}</span>
586	          <span class="panel-badge">#${i + 1} match</span>
587	        </div>
588	        <div class="panel-name">${displayName(c.name)}</div>
589	        <div class="panel-meta">${c.size || 'Unknown size'} · ${c.platform} · ${c.engagement_level || c.engagement || 'High engagement'}</div>
590	      </div>`;
591	  }).join('');
592	}
593	
594	function renderMap(communities) {
595	  const stage = document.getElementById('map-stage');
596	  stage.innerHTML = '';
597	  document.getElementById('map-ruler-label').textContent = communities.length + ' communities found';
598	  renderSidePanel(communities);
599	
600	  // center node
601	  const center = document.createElement('div');
602	  center.className = 'center-node';
603	  center.textContent = currentStartup.name;
604	  stage.appendChild(center);
605	
606	  const cx = stage.clientWidth / 2 || window.innerWidth / 2;
607	  const cy = stage.clientHeight / 2 || window.innerHeight / 2;
608	  const n = communities.length;
609	
610	  // Base bubble size per community, tamed down as the count grows so a busy
611	  // result set doesn't produce giant overlapping circles — but never so much
612	  // that the label text has nowhere to go.
613	  const sizeScale = n <= 6 ? 1 : Math.max(0.75, 6 / n);
614	  let sizes = communities.map(c => (65 + (c.relevance_score || 70) * 0.6) * sizeScale);
615	
616	  // Pick a radius large enough that adjacent bubbles (by circumference,
617	  // weighted by their own diameter) don't touch, then shrink everything
618	  // proportionally if that radius wouldn't fit on screen.
619	  const SPACING = 1.35;
620	  let totalDiameter = sizes.reduce((a, b) => a + b, 0);
621	  let radius = Math.max(170, (totalDiameter * SPACING) / (2 * Math.PI));
622	  const maxRadius = Math.min(cx, cy) * 0.78;
623	  if (radius > maxRadius) {
624	    const shrink = maxRadius / radius;
625	    sizes = sizes.map(s => s * shrink);
626	    radius = maxRadius;
627	  }
628	
629	  // Reserve a wedge at the top for the "N communities found" ruler so no
630	  // bubble ever lands underneath it, regardless of how many there are.
631	  const EXCLUDE_HALF = 0.6; // radians (~34°) kept clear at the top
632	  const startAngle = -Math.PI / 2 + EXCLUDE_HALF;
633	  const totalArc = 2 * Math.PI - 2 * EXCLUDE_HALF;
634	
635	  communities.forEach((c, i) => {
636	    const angle = startAngle + ((i + 0.5) / n) * totalArc;
637	    const x = radius * Math.cos(angle);
638	    const y = radius * Math.sin(angle);
639	    const score = c.relevance_score || 70;
640	    const size = sizes[i];
641	
642	    // connector line
643	    const dist = Math.sqrt(x * x + y * y);
644	    const angleDeg = Math.atan2(y, x) * (180 / Math.PI);
645	    const line = document.createElement('div');
646	    line.className = 'connector';
647	    line.style.width = dist + 'px';
648	    line.style.transform = `rotate(${angleDeg}deg)`;
649	    stage.appendChild(line);
650	
651	    // node
652	    const node = document.createElement('div');
653	    node.className = 'orbit-node';
654	    node.style.width = size + 'px';
655	    node.style.height = size + 'px';
656	    node.style.background = PLATFORM_COLORS[c.platform] || '#8a81b0';
657	    node.style.setProperty('--tx', x + 'px');
658	    node.style.setProperty('--ty', y + 'px');
659	    node.style.animationDelay = (i * 0.06) + 's';
660	    const cleanName = displayName(c.name);
661	    if (size < 46) {
662	      const scoreFont = Math.max(9, size * 0.22);
663	      node.innerHTML = `<div class="node-score" style="font-size:${scoreFont}px">${score}%</div>`;
664	    } else {
665	      // Shrink the name to fit fully (wrapping across up to ~2 lines)
666	      // rather than truncating with an ellipsis.
667	      const nameFont = Math.max(7, Math.min(12, (size * 0.85) / Math.max(6, cleanName.length * 0.42)));
668	      const scoreFont = Math.max(8, nameFont * 0.85);
669	      node.innerHTML = `<div class="node-name" style="font-size:${nameFont}px">${cleanName}</div><div class="node-score" style="font-size:${scoreFont}px">${score}%</div>`;
670	    }
671	    node.title = cleanName;
672	    node.onclick = () => generatePlaybook(c);
673	    stage.appendChild(node);
674	  });
675	}
