677	async function generatePlaybook(community) {
678	  goToScreen('screen-playbook');
679	  document.getElementById('pb-title').textContent = displayName(community.name);
680	  document.getElementById('pb-platform').textContent = community.platform;
681	  document.getElementById('pb-body').innerHTML = `
682	    <div class="center-loading">
683	      <div class="spinner"></div>
684	      <div style="color:var(--text2)">Generating activation playbook for ${community.name}...</div>
685	    </div>`;
686	
687	  try {
688	    const res = await fetch(`${API_BASE}/generate-playbook`, {
689	      method: 'POST',
690	      headers: { 'Content-Type': 'application/json' },
691	      body: JSON.stringify({
692	        startup: currentStartup,
693	        community_name: community.name,
694	        community_platform: community.platform,
695	        community_description: community.icp_match || '',
696	      }),
697	    });
698	    if (!res.ok) throw new Error(await res.text());
699	    const p = await res.json();
700	    renderPlaybook(p);
701	  } catch (err) {
702	    document.getElementById('pb-body').innerHTML =
703	      `<div style="color:var(--warning);padding:40px;">Error: ${err.message}</div>`;
704	  }
705	}
