709	  const dos = (p.dos || []).map(d => `<li>✓ ${d}</li>`).join('');
710	  const donts = (p.donts || []).map(d => `<li>✗ ${d}</li>`).join('');
711	
712	  document.getElementById('pb-body').innerHTML = `
713	    <div class="pb-grid">
